#!/usr/bin/env bun
import chokidar from 'chokidar';
import sade from 'sade';

import { bundle } from './bundle.js';
import { handleLightningCSSErrors } from './errors.js';
import { log } from './log.js';
import { generateMeta, generateRootCSS, loadConfig, writeToDisk } from './utils.js';

const CLI = sade('bd-css');

//
// BUILD PROD:
// Combines all @imports targeting the `main.css` file and any addons with the `dist` flag.
// Does not touch the `root.css` file in any way.
//
CLI.command('build')
	.describe('Compiles theme to the necessary files.')
	.action(async () => {
		const startTime = performance.now();
		const config = await loadConfig();

		let main: string = await bundle(config.main);

		if (config.addons) {
			for (let i = 0; i < config.addons.length; i++) {
				const addon = config.addons[i];
				const bundled = await bundle(addon.target);
				writeToDisk(addon.target.split('/').pop()!, bundled, 'dist');

				if (addon.dist) main += bundled + '\n';
			}
		}

		writeToDisk(config.meta.name + '.theme.css', generateRootCSS(config, { includeExternalImport: true }), 'dist');
		writeToDisk(config.meta.name + '.css', main, 'dist');

		if (config.static) {
			writeToDisk(config.meta.name + '.static.theme.css', generateRootCSS(config, { includeExternalImport: false }) + '\n' + main, 'dist');
		}

		const endTime = performance.now();

		log.success(`Built in ${(endTime - startTime).toFixed()}ms`);
	});

//
// DEV BUILD:
// Combines `root.css` and `main.css` and any addons with the `dev` flag
//
CLI.command('dev')
	.describe('Watch the SRC folder for changes and auto compile.')
	.action(async () => {
		const config = await loadConfig();

		chokidar
			.watch(['src', 'bd-css.config.js'])
			.on('ready', () => {
				console.log('');
				log.info(`Watching ${log.code('src')} folder for changes...`);
				log.info(`BetterDiscord: ${config.betterdiscord.themeFolder}`);
				if (config.vencord.dev) log.info(`Vencord: ${config.vencord.themeFolder}`);
				if (config.prettyfluxer) log.info(`PrettyFluxer: ${config.prettyfluxer.themeFolder}`);
				console.log('');
			})
			.on('change', async () => {
				try {
					const fileName = config.meta.name + '.theme.css';
					const date = new Date();
					const startTime = performance.now();

					let result = generateMeta(config.meta);

					const root = await Bun.file(config.root).text();
					const mainBundled = await bundle(config.main);

					result += root + '\n';
					result += mainBundled + '\n';

					if (config.addons) {
						for (let i = 0; i < config.addons.length; i++) {
							const addon = config.addons[i];
							if (addon.dev) {
								const bundled = await bundle(addon.target);
								result += `\n/* ${addon.target} */\n${bundled}`;
							}
						}
					}

					writeToDisk(fileName, result, config.betterdiscord.themeFolder);
					if (config.vencord.dev) writeToDisk(fileName, result, config.vencord.themeFolder);

					const endTime = performance.now();

					log.success(`${date.toLocaleTimeString()} - Built in ${(endTime - startTime).toFixed()}ms`);
				} catch (err) {
					handleLightningCSSErrors(err);
				}
			});
	});

CLI.parse(process.argv);
